// ---------------------------------------------------------------- Processes (agtop)

/** agtop's process with role, roleSource and roleEvidence. No numeric confidence: roleSource is the signal. */
export type ClassifiedProcessNode = AgentProcess
export type AgentProcessTree = AgtopProcessTree & { harnessId?: HarnessId }
export interface RoleInfo { role: ProcessRole; label: string; description: string; definitions: string[] }
export type ProcessListing =
  | { supported: true; trees: AgentProcessTree[]; accelerators: AcceleratorSnapshot | null; listedAt: number }
  | { supported: false; reason: string }
/** Serializable view of agtop's ManagedAgent (which holds a Promise and a function). */
export interface SpawnedAgent { jobId: string; pid: number; containmentMode: ContainmentMode }

export const CAPABILITIES = [
  'agtop.trees', 'agtop.kill', 'agtop.spawn-contained', 'agtop.roles', 'agtop.accelerators',
  'agtop.lemonade-probe', 'agtop.worktree-detect', 'agtop.daemon',
  'toolkit.select-target', 'toolkit.verify-unit', 'toolkit.plan-schema', 'toolkit.fix-brief',
  'acp.v1', 'acp.fs', 'acp.terminal',
  'sct.envelope-v1', 'sct.direct-hyperswarm', 'sct.direct-webrtc', 'sct.mailbox', 'sct.share-gate',
] as const
/** The `x.<name>` form lets a project addition register a capability without a change to the union. */
export type CapabilityId = (typeof CAPABILITIES)[number] | `x.${string}`

/** Discovery uses facts about the materialized pins, never version numbers. */
export interface CapabilitySet {
  present: CapabilityId[]
  missing: { capability: CapabilityId; reason: string }[]
  probedAt: number
  pins: { agtop: string; toolkit: string }
}

export type BoundaryIssue =
  | { code: 'major-mismatch'; got: number; want: number }
  | { code: 'missing-capability'; capability: CapabilityId }
  | { code: 'schema'; path: string; message: string }

/** A failed decode never reaches the store, the renderer, or the vault. */
export type Decoded<T> = { ok: true; value: T; ignoredFields: string[] } | { ok: false; issues: BoundaryIssue[] }

/** Validates a value that has no envelope, for example a return value of agtop. Unknown fields are dropped and listed. */
export function decodeBody<K extends EnvelopeKind>(kind: K, value: unknown): Decoded<BodyOf<K>> {
  const parsed = BODY_SCHEMAS[kind].safeParse(value)
  return parsed.success ? { ok: true, value: parsed.data as BodyOf<K>, ignoredFields: droppedFields(value, parsed.data) } : { ok: false, issues: schemaIssues(parsed.error) }
}

export type * from "./types.js";
export { listAgentTrees, spawnContainedAgent, killAgentTree } from "./manager.js";
export { getAcceleratorSnapshot } from "./accelerators.js";
export type { AcceleratorProvider, RawEngineSample } from "./accelerators.js";
export { resolveGitWorktree } from "./git.js";
export { probeLemonade } from "./backend.js";
export { startDaemon } from "./daemon.js";
export { ROLE_ORDER, ROLE_INFO, roleCatalog, classifyTreeRoles } from "./roles.js";

export interface SpawnAgentOptions {
  jobId?: string; harness: HarnessType; command: string; args?: string[]; cwd?: string;
  userOrPeer?: string; useLemonadeLocal?: boolean; lemonadeUrl?: string;
  extraEnv?: Record<string, string>; stdio?: "inherit" | "ignore";
  /** A writable, delegated cgroup v2 directory. Failure is fatal when supplied. */
  cgroupRoot?: string;
}
export interface ManagedAgent {
  jobId: string; pid: number; containmentMode: ContainmentMode;
  exited: Promise<number>;
  terminate(): Promise<KillResult>;
}
export interface KillResult { killedPids: number[]; failedPids: number[]; errors: string[] }
